SELECT (SELECT COUNT(*) FROM raw) raw_rows,(SELECT COUNT(*) FROM stays) merged_stays,(SELECT COUNT(*) FROM raw WHERE b<=a) zero_or_negative_rows,(SELECT COUNT(*) FROM facts WHERE raw_event=1 AND removing_rev IS NULL) missing_removers,(SELECT COUNT(*) FROM facts WHERE duration<0) negative_durations,(SELECT COUNT(*) FROM stays WHERE island>1) return_stays,(SELECT COUNT(*) FROM wtt.edit)-(SELECT COUNT(*) FROM end_edit) duplicate_timestamp_edits,(SELECT COUNT(DISTINCT page_id) FROM raw) pages;
